struct E { int u, v; double w; };

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    struct Orig { int u, v; long long d, c; };
    vector<Orig> orig;
    orig.reserve(m);
    for (int i = 0; i < m; ++i) {
        int u, v; long long d, c;
        cin >> u >> v >> d >> c;
        orig.push_back({u, v, d, c});
    }

    double hi = 0.0;
    for (auto &e : orig) {
        if (e.d > 0) {
            hi = max(hi, (double)e.c / (double)e.d);
        } else if (e.d == 0 && e.c > 0) {

            hi = max(hi, (double)e.c + 1.0);
        }
    }
    double lo = 0.0;

    auto check = [&](double t)->bool {

        vector<E> edges;
        edges.reserve(2 * m);
        for (auto &o : orig) {
            double w = t * (double)o.d - (double)o.c;
            edges.push_back({o.u, o.v, w});
            edges.push_back({o.v, o.u, w});
        }

        const double INF = 1e100;
        vector<double> dist(n+1, 0.0); 
        const double EPS = 1e-12;
        for (int iter = 1; iter <= n; ++iter) {
            bool any = false;
            for (auto &e : edges) {
                if (dist[e.v] > dist[e.u] + e.w + EPS) {
                    dist[e.v] = dist[e.u] + e.w;
                    any = true;
                }
            }
            if (!any) return false; 
            if (iter == n && any) return true; 
        }
        return false;
    };

    for (int it = 0; it < 60; ++it) {
        double mid = (lo + hi) / 2.0;
        if (check(mid)) {
            lo = mid; 
        } else {
            hi = mid;
        }
    }

    cout.setf(std::ios::fixed);
    cout << setprecision(12) << lo << "\n";
}